import useAxiosLarge from "../../hook/useAxiosLarge/useAxiosLarge";
import icons from "../../constants/Icons";

import "./Week.css";
import { useEffect, useState } from "react";

const Week = ({ city, temp }) => {
  const { dataL } = useAxiosLarge({ city: city });
  const count = [1, 2, 3, 4, 5];
  const [date, setDate] = useState([]);

  useEffect(() => {
    const today = new Date();
    const computedDates = count.map((elmC) => {
      const otherDay = new Date(today);
      otherDay.setDate(today.getDate() + elmC);

      const neededDay = String(otherDay.getDate()).padStart(2, "0");

      return dataL?.list.find(
        (elm) => elm.dt_txt.split(" ")[0].split("-")[2] === neededDay
      );
    });
    setDate(computedDates);
  }, [dataL, count]);

  // const weekDate = () => {
  //   const today = new Date();
  //   count.map((elmC) => {
  //     const otherDay = new Date(today);
  //     otherDay.setDate(today.getDate() + elmC);

  //     const neededDay = String(otherDay.getDate()).padStart(2, "0");

  //     const firstMatch = dataL?.list.find(
  //       (elm) => elm.dt_txt.split(" ")[0].split("-")[2] === neededDay
  //     );
  //     setDate(firstMatch);
  //   });
  // };
  // weekDate();
  const kelvinToCelsius = (num) => {
    return num - 273.15;
  };
  const kelvinToFar = (num) => {
    return ((num - 273.15) * 9) / 5 + 32;
  };

  return (
    <div className="mainWeek">
      {date.map((elm,id))}
      {date ?
          <div className="eachDay">
            <p className="date">{date[0]?.dt_txt.split(" ")[0].slice(5)}</p>
            <div className="tempWeek">
              {temp === "C" ? (
                <p className="temperature">
                  {Math.trunc(kelvinToCelsius(date[0]?.main.temp))} °C
                </p>
              ) : (
                <p className="temperature">
                  {Math.trunc(kelvinToFar(date[0]?.main.temp))} °F
                </p>
              )}
              {icons.map((elm) =>
                elm.weather === date[0]?.weather[0].main ? (
                  <img src={elm.icon} className="icon" alt="weatherIcon" />
                ) : null
              )}
            </div>
          </div>
         : (
          <div className="eachDay">
            <p className="date">N/A</p>
            <p className="temperature">N/A</p>
          </div>
        )
      }
    </div>
  );
};

export default Week;
